import {GAME} from './config.js';
import * as E from './engine.js';
import {MODERN} from './catalog.js';
export const workerStatus=w=>({idle:'Libre',walk:'Hacia el recurso',gather:'Recogiendo materiales',return:'Entregando carga',waiting:'Almacén lleno',blocked:'Esperando acceso',move:'Cambiando de posición'}[w.mode]||'Libre');
export function workersPanel(s,h){const{panelHead,img,esc,cost,clock,fmt}=h,f=s.workforce,free=E.freeWorkers(s).length;
 return panelHead('POBLACIÓN CIVIL',MODERN?'Dirige a tus obreros.':'Dirige a tus colonos.')+'<p class="intro">Selecciona un trabajador y toca un árbol, yacimiento o destino en el mapa. Los materiales cuentan cuando llegan al almacén o al edificio principal.</p><div class="civil-summary"><b>'+free+' libres</b><b>'+f.workers.length+' / '+E.workerCapacity(s)+' alojados</b><b>'+fmt(f.delivered)+' entregados</b></div><div class="action-row"><button data-action="select-workers">Seleccionar todos</button><button data-action="hire-worker" '+(f.workers.length+f.training.length>=E.workerCapacity(s)?'disabled':'')+'>Contratar · 18 s</button></div>'+cost(E.workerHireCost(s))+(f.training.length?'<div class="warning">'+f.training.length+' en preparación · siguiente en '+clock(f.training[0].ends-s.time)+'</div>':'')+'<div class="worker-list">'+f.workers.map((w,i)=>'<article class="worker-card">'+img('settler',1,true)+'<div><h3>'+(MODERN?'Obrero ':'Colono ')+(i+1)+'</h3><p>'+workerStatus(w)+(w.cargo>0?' · '+fmt(w.cargo)+' '+esc(GAME.resources[w.resource].name):'')+'</p><small>'+(w.order?.kind==='gather'?'Recurso en '+w.order.x+', '+w.order.y:'Posición '+Math.floor(w.x)+', '+Math.floor(w.y))+'</small><div class="action-row"><button data-action="select-worker" data-id="'+w.id+'">Ver y dirigir</button><button data-action="worker-wood" data-id="'+w.id+'">Buscar madera</button></div></div></article>').join('')+'</div><p class="tiny">Cada trabajador lleva hasta 20 materiales. Mejora el edificio principal o añade talleres para ampliar el alojamiento. Se refugian durante las batallas y descansan cuando cierras el juego.</p>';
}
export function civilianInspector(s,selected,h){const{img,esc,fmt,icon}=h,workers=s.workforce.workers.filter(w=>selected.includes(w.id)),match=/^resource:(\d+):(\d+)$/.exec(selected[0]||''),n=match&&E.resourceNode(s,+match[1],+match[2]),close='<button class="close" data-action="deselect" aria-label="Cerrar selección">'+icon('close')+'</button>';
 if(n)return'<div class="panel-top"><div><div class="eyebrow">RECURSO NATURAL</div><h2>'+n.name+'</h2></div>'+close+'</div>'+img(n.kind)+'<div class="stat-row"><span>Material</span><strong>'+esc(GAME.resources[n.resource].name)+'</strong></div><div class="stat-row"><span>Disponible</span><strong>'+fmt(n.remaining)+' / '+n.total+'</strong></div><div class="progress"><span style="width:'+n.remaining/n.total*100+'%"></span></div><p>Los trabajadores extraen materiales y los transportan. Al agotarse, esta casilla queda libre para construir.</p><button class="primary wide" data-action="send-worker" data-x="'+n.x+'" data-y="'+n.y+'" '+(!E.freeWorkers(s).length?'disabled':'')+'>Enviar trabajador libre</button><button class="wide" data-action="tab" data-type="workers">Gestionar trabajadores</button>';
 if(!workers.length)return null;const cargo=workers.reduce((v,w)=>v+w.cargo,0),w=workers[0];return'<div class="panel-top"><div><div class="eyebrow">CONTROL CIVIL</div><h2>'+(workers.length>1?workers.length+' trabajadores':MODERN?'Obrero seleccionado':'Colono seleccionado')+'</h2></div>'+close+'</div>'+img('settler',1,true,'hero-image')+'<div class="stat-row"><span>Actividad</span><strong>'+(workers.length===1?workerStatus(w):'Órdenes de grupo')+'</strong></div><div class="stat-row"><span>Carga pendiente</span><strong>'+fmt(cargo)+' / '+workers.length*20+'</strong></div><p>Toca un recurso para trabajar o suelo libre para moverte. La carga pendiente se entrega antes de cambiar de tarea.</p><button class="primary wide" data-action="worker-target">Marcar destino en el mapa</button><div class="action-row"><button data-action="worker-wood">Buscar madera</button><button data-action="worker-ore">Buscar '+(MODERN?'oro':'piedra')+'</button></div><button class="wide" data-action="stop-workers">Detener y entregar carga</button>'+(workers.some(w=>w.mode==='waiting')?'<p class="warning">El almacén está lleno. Gasta materiales o mejora el almacenamiento; la carga se conserva.</p>':'')+(workers.some(w=>w.mode==='blocked')?'<p class="warning">No hay un paso o un punto de trabajo libre. Volverá a intentarlo; la carga se conserva.</p>':'');
}
export function progressContent(s,h){const{head,img,fmt,esc}=h,p=E.experience(s),next=E.futureUnlocks(s);return head('EXPERIENCIA DEL COMANDANTE','Nivel '+p.level)+'<div class="xp-total"><b>★ '+p.level+'</b><div><strong>'+fmt(p.xp)+' XP</strong><p>'+(p.next===null?'Experiencia máxima':fmt(p.remaining)+' XP para el siguiente nivel')+'</p></div></div><div class="progress"><span style="width:'+p.ratio*100+'%"></span></div><p>Gana experiencia entregando materiales, recogiendo producción, terminando obras, entrenando tropas y cumpliendo encargos.</p><h3>Próximos desbloqueos</h3><p class="tiny">Necesitas la experiencia indicada y el nivel requerido de '+GAME.hq.toLowerCase()+'. Las tropas también requieren su edificio de entrenamiento.</p><div class="unlock-list">'+next.slice(0,8).map(x=>'<article>'+img(x.type,1,x.unit)+'<div><h3>'+esc(x.name)+'</h3><small>Comandante '+x.level+' · '+GAME.hq+' '+x.hq+'</small></div></article>').join('')+'</div>'+(!next.length?'<p>Todos los requisitos de experiencia del catálogo están disponibles.</p>':'')+'<p class="tiny">Los edificios y las tropas que ya tienes se conservan al actualizar el juego.</p>';}
